var n=[{title:`Patrones a corto y a largo plazo`,text:`Los atletas avanzados a veces usan a propósito el sobrealcance funcional, y su rendimiento se recupera tras una recuperación suficiente. El sobrealcance no funcional causa una caída más larga del rendimiento sin ninguna ganancia útil. El síndrome de sobreentrenamiento es una afección duradera con muchos factores que contribuyen, y necesita una valoración profesional que descarte otras causas.`},{title:`Señales de aviso`,text:`Las caídas repetidas del rendimiento, una fatiga desproporcionada respecto a tu entrenamiento, una irritabilidad inusual, el sueño alterado, la motivación en descenso y las agujetas persistentes pueden ser señales de aviso. Ninguna es específica del sobreentrenamiento. El estrés laboral, la enfermedad, comer poco y muchas afecciones médicas pueden causar los mismos síntomas.`},{title:`Reduce el estrés antes de añadir más`,text:`Si varias sesiones te resultan inusualmente duras y tu rendimiento baja, reduce durante un tiempo el volumen o la intensidad, toma más recuperación y revisa tu sueño y tu carga total de entrenamiento. Una semana más ligera puede tener sentido, pero cuánto recortar varía de una persona a otra. No intentes «aguantar» una fatiga que sigue empeorando con un esfuerzo máximo tras otro.`},{title:`Evita la sobrecarga crónica`,text:`Aumenta el entrenamiento de forma gradual, espacia los entrenamientos duros y vigila las tendencias en las repeticiones completadas, el RPE y lo preparado que te sientes. Planifica periodos fáciles cuando los viajes, la enfermedad, el trabajo intenso u otras demandas se sumen a tu estrés total. Las sesiones extra solo ayudan si tu cuerpo puede adaptarse a ellas.`},{title:`Cómo usar TrainUp`,text:`La semana 4 de cada plan es una semana de descarga más ligera. Cuando vuelves a generar el plan, este cambia un paso cada vez y nunca a partir de menos de 3 entrenamientos. Si 2 de tus últimos 3 entrenamientos fueron muy duros (RPE 9 o más) o se completaron en menos de un 60 %, el siguiente plan es más fácil. TrainUp no diagnostica ni trata el síndrome de sobreentrenamiento. Si la tendencia a la baja continúa, descansa y busca consejo profesional.`}];var s=[{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026: dosis de ejercicio, recuperación y progresión`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC12965823/`},{label:`CDC: recomendaciones de sueño para adultos`,url:`https://www.cdc.gov/sleep/about/index.html/`}];var o={sections:n,sources:s};export{o as default,n as sections,s as sources};